// Auto-detect whichever binary key holds the attachment and normalize it to 'data'.
// Also extract a clean sender email address, since raw (non-simplified) Gmail data
// returns 'from' as a header object instead of a plain string.
const items = $input.all();
const output = [];

function extractEmail(raw) {
  if (!raw) return '';
  if (typeof raw === 'string') {
    const match = raw.match(/<([^>]+)>/);
    return match ? match[1] : raw.trim();
  }
  if (typeof raw === 'object') {
    if (raw.value && Array.isArray(raw.value) && raw.value[0]) return raw.value[0].address || extractEmail(raw.value[0].name);
    if (raw.text) return extractEmail(raw.text);
    if (raw.address) return raw.address;
  }
  return '';
}

for (const item of items) {
  const binaryKeys = Object.keys(item.binary || {});
  if (binaryKeys.length === 0) {
    throw new Error('No attachment found on this email. Make sure the email actually has a PDF attached, and that "Download Attachments" is enabled on the Gmail Trigger node.');
  }
  const pdfKey = binaryKeys.find(k => (item.binary[k].fileName || '').toLowerCase().endsWith('.pdf')) || binaryKeys[0];

  // Find the From header, whether it's a simplified string field or raw headers array
  let fromRaw = item.json.from;
  if (!fromRaw && Array.isArray(item.json.payload && item.json.payload.headers)) {
    const header = item.json.payload.headers.find(h => (h.name || '').toLowerCase() === 'from');
    fromRaw = header ? header.value : '';
  }
  const fromEmail = extractEmail(fromRaw);

  output.push({
    json: { ...item.json, fromEmail },
    binary: {
      data: item.binary[pdfKey]
    }
  });
}

return output;

// Robustly extract plain text from the Gemini response, whatever shape it comes in
const items = $input.all();
const output = [];

function findText(obj) {
  if (typeof obj === 'string') return obj;
  if (!obj || typeof obj !== 'object') return '';
  if (typeof obj.text === 'string') return obj.text;
  if (typeof obj.content === 'string') return obj.content;
  if (obj.content) return findText(obj.content);
  if (Array.isArray(obj.parts) && obj.parts[0]) return findText(obj.parts[0]);
  if (obj.message) return findText(obj.message);
  if (Array.isArray(obj.candidates) && obj.candidates[0]) return findText(obj.candidates[0]);
  return JSON.stringify(obj);
}

for (const item of items) {
  const text = findText(item.json.content ?? item.json);
  output.push({ json: { ...item.json, resultText: text } });
}

return output;
